//! Settings → About (Plan 3 Task 21). `about_info` is the text of the tab; `fill` puts it on the window.
use super::strings as tr;
use crate::{
    ui::{SettingsAboutWindow, operator::{view::OperatorSnapshot, window::VideoInfo}},
    video::DrawMode,
};

/// Generated by `cargo about` (see `about.toml`); CI fails if it no longer matches `Cargo.lock`.
const CRATE_LICENSES: &str = include_str!("../../../THIRD-PARTY-LICENSES.txt");
/// What ships beside the program and so is not in `Cargo.lock`: libmpv, FFmpeg, pdfium, the fonts.
const NATIVE_LICENSES: &str = include_str!("../../../packaging/licenses/native.txt");

#[derive(Clone, Debug, PartialEq)]
pub struct AboutInfo { pub version: String, pub data_folder: String, pub video: String, pub mpv: String }

pub fn about_info(snap: &OperatorSnapshot, info: &VideoInfo) -> AboutInfo {
    AboutInfo { version: snap.version.clone(), data_folder: snap.data_folder.clone(), video: video_line(info), mpv: mpv_line(info) }
}

fn video_line(info: &VideoInfo) -> String {
    match (&info.mpv, info.draw_mode) {
        (None, _) => tr::ABOUT_VIDEO_MISSING,
        (Some(_), DrawMode::OpenGl) => tr::ABOUT_VIDEO_GPU,
        (Some(_), DrawMode::Software) => tr::ABOUT_VIDEO_SOFTWARE,
    }.into()
}

/// Empty until the versions are read, and when the player is missing: the tab then leaves the line out.
fn mpv_line(info: &VideoInfo) -> String {
    info.mpv.as_ref().and_then(|m| m.versions.as_ref()).map(|(mpv, ffmpeg)| tr::about_versions(mpv, ffmpeg)).unwrap_or_default()
}

/// The text behind **Show licenses**.
pub fn licenses() -> String { format!("{CRATE_LICENSES}\n{NATIVE_LICENSES}") }

pub fn fill(ui: &SettingsAboutWindow, about: &AboutInfo) {
    ui.set_version(about.version.as_str().into());
    ui.set_data_folder(about.data_folder.as_str().into());
    ui.set_video(about.video.as_str().into());
    ui.set_mpv(about.mpv.as_str().into());
    ui.set_credit(tr::about_video_credit().into());
    ui.set_licenses(licenses().into());
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{app::test_app, ui::{operator::window::MpvInfo, ui_test_init}};
    use i_slint_backend_testing::ElementHandle;
    use slint::{ComponentHandle, platform::PointerEventButton};

    fn player(versions: Option<(&str, &str)>) -> Option<MpvInfo> {
        Some(MpvInfo { api: (2, 3), path: "libmpv-2.dll".into(), versions: versions.map(|(m, f)| (m.into(), f.into())) })
    }

    fn snapshot() -> OperatorSnapshot { OperatorSnapshot::read(&test_app()) }

    fn window(about: &AboutInfo) -> SettingsAboutWindow {
        ui_test_init();
        let ui = SettingsAboutWindow::new().unwrap();
        fill(&ui, about);
        ui.show().unwrap();
        ui
    }

    fn count(ui: &SettingsAboutWindow, id: &str) -> usize { ElementHandle::find_by_element_id(ui, id).count() }

    #[test]
    fn about_shows_aboutslint() {
        let ui = window(&about_info(&snapshot(), &VideoInfo { draw_mode: DrawMode::OpenGl, mpv: player(None) }));
        assert_eq!(ElementHandle::find_by_element_type_name(&ui, "AboutSlint").count(), 1);
    }

    #[test]
    fn about_info_reports_software_mode() {
        let got = about_info(&snapshot(), &VideoInfo { draw_mode: DrawMode::Software, mpv: player(Some(("mpv v0.41.0", "n8.0"))) });
        assert_eq!(got.video, "Video: software drawing");
        assert_eq!(got.mpv, "mpv v0.41.0 · FFmpeg n8.0");
    }

    #[test]
    fn about_info_reports_gpu_mode() {
        let got = about_info(&snapshot(), &VideoInfo { draw_mode: DrawMode::OpenGl, mpv: player(None) });
        assert_eq!(got.video, "Video: GPU (OpenGL)");
        assert_eq!(got.mpv, "", "versions not read yet");
    }

    #[test]
    fn about_info_reports_missing_player() {
        let got = about_info(&snapshot(), &VideoInfo { draw_mode: DrawMode::OpenGl, mpv: None });
        assert_eq!(got.video, "Video player missing");
        assert_eq!(got.mpv, "");
    }

    #[test]
    fn about_info_carries_version_and_data_folder() {
        let snap = snapshot();
        let got = about_info(&snap, &VideoInfo { draw_mode: DrawMode::Software, mpv: None });
        assert_eq!((got.version.as_str(), got.data_folder.as_str()), (snap.version.as_str(), snap.data_folder.as_str()));
        assert!(!got.version.is_empty());
    }

    #[test]
    fn licenses_text_mentions_slint_and_libmpv() {
        let text = licenses();
        assert!(text.contains("Slint"));
        assert!(text.contains("libmpv"));
    }

    #[test]
    fn credit_names_both_lgpl_libraries() {
        let credit = tr::about_video_credit();
        assert!(credit.starts_with("Video playback uses libmpv (LGPL-2.1+) and FFmpeg libraries under the LGPLv2.1 — source: "));
    }

    #[test]
    fn show_licenses_opens_the_text() {
        let ui = window(&about_info(&snapshot(), &VideoInfo { draw_mode: DrawMode::Software, mpv: None }));
        assert_eq!(count(&ui, "SettingsAbout::licenses-text"), 0);
        ElementHandle::find_by_element_id(&ui, "SettingsAbout::licenses-btn").next().unwrap().mock_single_click(PointerEventButton::Left);
        assert_eq!(count(&ui, "SettingsAbout::licenses-text"), 1);
        assert_eq!(ui.get_licenses(), licenses().as_str());
    }

    #[test]
    fn versions_line_only_when_known() {
        let shown = |mpv| count(&window(&about_info(&snapshot(), &VideoInfo { draw_mode: DrawMode::Software, mpv })), "SettingsAbout::mpv-text");
        assert_eq!(shown(player(None)), 0);
        assert_eq!(shown(player(Some(("mpv v0.41.0", "n8.0")))), 1);
    }
}
